/**
 * Re-points every issue carrying `sourceLabelId` at `targetLabelId`, then drops
 * the source label, all in one transaction. Issues that already carry the
 * target are left with a single target row. Returns how many issues carried
 * the source before the merge.
 */
export async function mergeLabel(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const sourceIssueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all()
      .map((row) => row.issueId);

    if (sourceIssueIds.length > 0) {
      // The (issue_id, label_id) unique index turns re-tagging an issue that
      // already carries the target into a no-op rather than an error.
      tx.insert(issueLabels)
        .values(
          sourceIssueIds.map((issueId) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .onConflictDoNothing()
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(
        and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)),
      )
      .run();

    return sourceIssueIds.length;
  });
}

