/**
 * Folds the source label into the target: every issue that carried the source
 * carries the target instead, then the source label is removed. Merging deletes
 * a label, so it takes the same permission as `deleteLabel`.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  // The schema rejects this too, but callers may skip it.
  if (input.sourceLabelId.toUpperCase() === input.targetLabelId.toUpperCase()) {
    throw new Error("A label cannot be merged into itself");
  }

  const target = requireFound(
    await labelRepo.findLabelById(input.orgId, input.targetLabelId),
    "Label",
    input.targetLabelId,
  );
  requireFound(
    await labelRepo.findLabelById(input.orgId, input.sourceLabelId),
    "Label",
    input.sourceLabelId,
  );

  const issuesRelabelled = await labelRepo.mergeLabel(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );
  return { label: target, issuesRelabelled };
}

