import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import { TenantScopeError } from "@/lib/tenant";
import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import type { LabelId } from "@/types/common";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;
let defect: LabelId;
let bug: LabelId;
let i1: string, i2: string, i3: string, i4: string, i5: string;
let acmeLabel: LabelId;

function labelsOf(issueId: string): string[] {
  return getDb()
    .select({ labelId: issueLabels.labelId })
    .from(issueLabels)
    .where(eq(issueLabels.issueId, issueId))
    .all()
    .map((r) => r.labelId)
    .sort();
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("northwind");
  acme = await createTenant("acme");
  const a = north.actors.owner;

  const d = await labelService.createLabel(a, { orgId: north.org.id, name: "defect", color: "#ff0000", description: null });
  const b = await labelService.createLabel(a, { orgId: north.org.id, name: "bug", color: "#00ff00", description: "b" });
  defect = d.id;
  bug = b.id;
  const ac = await labelService.createLabel(acme.actors.owner, { orgId: acme.org.id, name: "defect", color: "#ff0000", description: null });
  acmeLabel = ac.id;

  const mk = async (title: string, labelIds: LabelId[]) =>
    (await issueService.createIssue(a, { ...issueInput(north.org.id, north.project.id, { title }), labelIds })).id as string;

  i1 = await mk("only defect", [defect]);
  i2 = await mk("both", [defect, bug]);
  i3 = await mk("only bug", [bug]);
  i4 = await mk("archived defect", [defect]);
  i5 = await mk("none", []);
  getDb().update(issues).set({ archivedAt: new Date().toISOString() }).where(eq(issues.id, i4)).run();
});

afterAll(() => cleanup());

describe("mergeLabels", () => {
  it("rejects a tenant mismatch", async () => {
    await expect(
      labelService.mergeLabels(north.actors.owner, { orgId: acme.org.id, sourceLabelId: defect, targetLabelId: bug }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("rejects a member without project:archive", async () => {
    await expect(
      labelService.mergeLabels(north.actors.member, { orgId: north.org.id, sourceLabelId: defect, targetLabelId: bug }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("rejects same-id input that skipped the schema, changing nothing", async () => {
    await expect(
      labelService.mergeLabels(north.actors.owner, { orgId: north.org.id, sourceLabelId: bug, targetLabelId: bug }),
    ).rejects.toThrow();
    expect(labelsOf(i2)).toEqual([defect, bug].sort());
    expect(getDb().select().from(labels).where(eq(labels.id, bug)).get()).toBeTruthy();
  });

  it("rejects a label id from another org, changing nothing", async () => {
    await expect(
      labelService.mergeLabels(north.actors.owner, { orgId: north.org.id, sourceLabelId: defect, targetLabelId: acmeLabel }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(getDb().select().from(labels).where(eq(labels.id, acmeLabel)).get()).toBeTruthy();
    expect(getDb().select().from(labels).where(eq(labels.id, defect)).get()).toBeTruthy();
    expect(labelsOf(i1)).toEqual([defect]);
  });

  it("schema rejects identical ids", () => {
    expect(
      mergeLabelsSchema.safeParse({ orgId: north.org.id, sourceLabelId: bug, targetLabelId: bug.toLowerCase() }).success,
    ).toBe(false);
    expect(
      mergeLabelsSchema.safeParse({ orgId: north.org.id, sourceLabelId: defect, targetLabelId: bug }).success,
    ).toBe(true);
  });

  it("merges defect into bug", async () => {
    const result = await labelService.mergeLabels(north.actors.owner, {
      orgId: north.org.id,
      sourceLabelId: defect,
      targetLabelId: bug,
    });
    expect(result.issuesRelabelled).toBe(3);
    expect(result.label.id).toBe(bug);
    expect(result.label.name).toBe("bug");
    expect(result.label.color).toBe("#00ff00");
    expect(result.label.description).toBe("b");

    expect(labelsOf(i1)).toEqual([bug]);
    expect(labelsOf(i2)).toEqual([bug]);
    expect(labelsOf(i3)).toEqual([bug]);
    expect(labelsOf(i4)).toEqual([bug]);
    expect(labelsOf(i5)).toEqual([]);
    expect(getDb().select().from(labels).where(eq(labels.id, defect)).get()).toBeUndefined();
    expect(getDb().select().from(labels).where(eq(labels.id, acmeLabel)).get()).toBeTruthy();
  });

  it("second merge of a now-missing source is not found and changes nothing", async () => {
    await expect(
      labelService.mergeLabels(north.actors.owner, { orgId: north.org.id, sourceLabelId: defect, targetLabelId: bug }),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(labelsOf(i1)).toEqual([bug]);
  });
});

